__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"HELP",{enumerable:!0,get:function(){return n}});const n=[{id:'start',icon:'rocket',title:'Za\u010d\xedn\xe1me',items:[{q:'\xda\u010det, nebo bez registrace?',a:'Na \xfavodn\xed obrazovce se m\u016f\u017ee\u0161 zaregistrovat e-mailem, nebo klepnout na \u201eZa\u010d\xedt hned bez registrace\u201c. Bez \xfa\u010dtu si zapisuje\u0161 tr\xe9ninky jen pro sebe; po prvn\xedm tr\xe9ninku ti aplikace nab\xeddne vytvo\u0159it \xfa\u010det a nic se neztrat\xed. \xda\u010det pot\u0159ebuje\u0161 pro p\u0159\xe1tele, zpr\xe1vy, tren\xe9ra a v\xfdzvu m\u011bs\xedce.'},{q:'\xdavodn\xed pr\u016fvodce',a:'P\u0159i prvn\xedm spu\u0161t\u011bn\xed se t\u011b aplikace zept\xe1 na p\xe1r v\u011bc\xed (jak dlouho tr\xe9nuje\u0161, kolikr\xe1t t\xfddn\u011b, jestli m\xe1\u0161 tren\xe9ra a jak\xe1 m\xe1\u0161 maxima) a podle toho doporu\u010d\xed pl\xe1n z knihovny. M\u016f\u017ee\u0161 ho p\u0159esko\u010dit.'},{q:'Prohl\xeddka ovl\xe1d\xe1n\xed',a:'Kr\xe1tk\xe1 prohl\xeddka postupn\u011b zv\xfdrazn\xed hlavn\xed \u010d\xe1sti aplikace a vysv\u011btl\xed je. Spust\xed\u0161 ji kdykoli tady naho\u0159e tla\u010d\xedtkem \u201eSpustit prohl\xeddku\u201c.'},{q:'Spodn\xed li\u0161ta',a:'Lev = Svaz (z\xe1vody a novinky) \xb7 \u010dinka = Tr\xe9ninky \xb7 tla\u010d\xedtko p\u0159ehr\xe1t = V\xfdzva m\u011bs\xedce \xb7 ozuben\xe9 kolo = Nastaven\xed \xb7 tvoje fotka = Profil. Klepnut\xed na ikonu sekce, ve kter\xe9 u\u017e jsi, t\u011b vr\xe1t\xed na jej\xed za\u010d\xe1tek.'},{q:'Jazyk, jednotky, vzhled',a:'Nastaven\xed \u2192 Vzhled a Tr\xe9ninky: \u010de\u0161tina, sloven\u0161tina nebo angli\u010dtina, sv\u011btl\xfd \u010di tmav\xfd vzhled, kilogramy nebo libry, v\xe1ha osy a d\xe9lka pauzy.'}]},{id:'csv',icon:'newspaper',title:'Svaz \u2013 z\xe1vody a novinky',items:[{q:'Kalend\xe1\u0159 z\xe1vod\u016f',a:'Z\xe1lo\u017eka \u201eKalend\xe1\u0159 z\xe1vod\u016f\u201c ukazuje nadch\xe1zej\xedc\xed a prob\u011bhl\xe9 z\xe1vody a v\xfdsledky. Barva u z\xe1vodu: \u010derven\xe1 = M\u010cR, modr\xe1 = liga, \u0161ed\xe1 = ostatn\xed sout\u011b\u017ee. Klepnut\xedm na z\xe1vod otev\u0159e\u0161 detail s p\u0159\xedlohami (propozice, startovky, v\xfdsledky).'},{q:'Novinky',a:'Z\xe1lo\u017eka \u201eNovinky\u201c p\u0159eb\xedr\xe1 \u010dl\xe1nky z webu vzpirani.cz. Klepnut\xedm otev\u0159e\u0161 cel\xfd \u010dl\xe1nek.'},{q:'Hled\xe1n\xed vzp\u011bra\u010d\u016f a klub\u016f',a:'Do pole naho\u0159e napi\u0161 jm\xe9no nebo klub. Ve v\xfdsledc\xedch p\u0159ep\xedn\xe1\u0161 mezi Vzp\u011bra\u010di a Kluby. Profil klubu ukazuje adresu, kontakty a \u010dleny, kte\u0159\xed maj\xed aplikaci.'},{q:'Bez sign\xe1lu',a:'Kdy\u017e se data nena\u010dtou, uk\xe1\u017ee se posledn\xed ulo\u017een\xe1 verze s upozorn\u011bn\xedm. St\xe1hnut\xedm seznamu dol\u016f obsah obnov\xed\u0161.'}]},{id:'plans',icon:'calendar',title:'Tr\xe9ninkov\xe9 pl\xe1ny',items:[{q:'Vytvo\u0159en\xed pl\xe1nu',a:'Tr\xe9ninky \u2192 tla\u010d\xedtko + vpravo naho\u0159e (nebo Pl\xe1ny \u2192 Vytvo\u0159it pl\xe1n). Pr\u016fvodce m\xe1 3 kroky: n\xe1zev a d\xe9lka pl\xe1nu, dny v t\xfddnu, cviky pro ka\u017ed\xfd den.'},{q:'S\xe9rie, opakov\xe1n\xed a z\xe1t\u011b\u017e',a:'U cviku nastav\xed\u0161 po\u010det n\xe1stup\u016f \xd7 opakov\xe1n\xed a z\xe1t\u011b\u017e: procenta z maxima (20\u2013150 %, aplikace dopo\u010d\xedt\xe1 kila podle tv\xfdch maxim), p\u0159esn\xe1 kila, RPE (n\xe1ro\u010dnost 1\u201310) nebo bez z\xe1t\u011b\u017ee. Jeden cvik m\u016f\u017ee m\xedt v\xedc \u0159\xe1dk\u016f, nap\u0159. 3 \xd7 2 @ 75 % a 2 \xd7 1 @ 85 %.'},{q:'T\xfddenn\xed progrese',a:'U pl\xe1nu m\u016f\u017ee\u0161 nastavit, o kolik procent se m\xe1 ka\u017ed\xfd t\xfdden p\u0159id\xe1vat (nap\u0159. +2,5 %). V\xe1hy v procentech se pak samy zvy\u0161uj\xed; na kart\u011b pl\xe1nu vid\xed\u0161 \u201eT\xfdden 2 z 6\u201c.'},{q:'Aktivace a zm\u011bny',a:'Aktivn\xed je v\u017edy jen jeden pl\xe1n \u2013 ten se ukazuje v Tr\xe9ninky \u2192 Dnes. Pl\xe1n m\u016f\u017ee\u0161 upravit, zkop\xedrovat, archivovat nebo \u201ezm\u011bnit od p\u0159\xed\u0161t\xedho t\xfddne\u201c (star\xe1 verze z\u016fstane v historii).'},{q:'Knihovna hotov\xfdch pl\xe1n\u016f',a:'Pl\xe1ny \u2192 Knihovna hotov\xfdch pl\xe1n\u016f: za\u010d\xe1te\u010dn\xedk, technika, silov\xfd blok, p\u0159\xedprava na z\xe1vod, pl\xe1n podle pocitu (RPE) a dal\u0161\xed. Filtruj podle \xfarovn\u011b a c\xedle, otev\u0159i n\xe1hled v\u0161ech dn\u016f a klepni na \u201eZa\u010d\xedt podle pl\xe1nu\u201c nebo \u201eNejd\u0159\xedv upravit\u201c.'},{q:'Pl\xe1n od tren\xe9ra',a:'Kdy\u017e ti tren\xe9r po\u0161le pl\xe1n, objev\xed se v Tr\xe9ninky \u2192 Dnes s ozna\u010den\xedm \u201ePl\xe1n od tren\xe9ra\u201c a dostane\u0161 upozorn\u011bn\xed. \xdapravy od tren\xe9ra se ti prom\xedtnou automaticky.'}]},{id:'workout',icon:'barbell',title:'Tr\xe9nink',items:[{q:'Za\u010d\xedt tr\xe9nink',a:'Tr\xe9ninky \u2192 Dnes \u2192 Za\u010d\xedt tr\xe9nink. Cviky a v\xe1hy se p\u0159edvypln\xed podle pl\xe1nu. Bez pl\xe1nu zvol \u201eVoln\xfd tr\xe9nink\u201c a cviky p\u0159id\xe1vej s\xe1m, nebo \u201eZopakovat posledn\xed\u201c.'},{q:'Od\u0161krt\xe1v\xe1n\xed n\xe1stup\u016f',a:'Klepni na kole\u010dko vpravo u n\xe1stupu \u2013 od\u0161krtne se a spust\xed se \u010dasova\u010d pauzy. Klepnut\xedm na \u201eopakov\xe1n\xed \xd7 kg\u201c zm\u011bn\xed\u0161 v\xe1hu nebo po\u010det opakov\xe1n\xed. Ikonou se dv\u011bma fajfkami od\u0161krtne\u0161 v\u0161echny n\xe1stupy cviku najednou.'},{q:'\u010casova\u010d pauzy',a:'Po od\u0161krtnut\xed b\u011b\u017e\xed dole odpo\u010det (d\xe9lku nastav\xed\u0161 v Nastaven\xed). Tla\u010d\xedtky \u221230 s / +30 s ho uprav\xed\u0161. Na konci zazn\xed zvuk a uk\xe1\u017ee se dal\u0161\xed n\xe1stup, kter\xfd jde od\u0161krtnout p\u0159\xedmo z li\u0161ty. \u010casova\u010d b\u011b\u017e\xed i na zam\u010den\xe9 obrazovce a na hodink\xe1ch.'},{q:'Rozcvi\u010dka a dopl\u0148ky',a:'Naho\u0159e v tr\xe9ninku: \u201eRozcvi\u010dka\u201c p\u0159id\xe1 seznam k od\u0161krt\xe1n\xed (nepo\u010d\xedt\xe1 se do n\xe1stup\u016f ani ton\xe1\u017ee), \u201eP\u0159idat dopl\u0148ky\u201c p\u0159id\xe1 dopl\u0148kov\xe9 cviky na konec. Vlastn\xed seznamy si ulo\u017e\xed\u0161 v N\xe1stroje \u2192 Rozcvi\u010dky a dopl\u0148ky a ke dni pl\xe1nu je p\u0159i\u0159ad\xed\u0161 v editoru pl\xe1nu.'},{q:'N\xe1vrh vah podle formy',a:'Kdy\u017e m\xe1\u0161 v den\xedku regenerace n\xedzkou p\u0159ipravenost, aplikace nab\xeddne ubrat v\xe1hy o 5 %. Kdy\u017e ti cvik minule \u0161el lehce (RPE 7 a m\xe9n\u011b), nab\xeddne p\u0159idat 2,5 kg; kdy\u017e byl t\u011b\u017ek\xfd, doporu\u010d\xed v\xe1hu dr\u017eet. Je to jen n\xe1vrh \u2013 pou\u017eije\u0161 ho klepnut\xedm.'},{q:'Dokon\u010den\xed tr\xe9ninku',a:'Hotovo \u2192 vypl\u0148 n\xe1ro\u010dnost (RPE), pocit, t\u011blesnou hmotnost a pozn\xe1mku (nepovinn\xe9) \u2192 Dokon\u010dit tr\xe9nink. Ulo\u017e\xed se jen od\u0161krtnut\xe9 n\xe1stupy. N\xe1sleduje oslava se shrnut\xedm a p\u0159\xedpadn\xfdmi nov\xfdmi rekordy.'},{q:'Sd\xedlen\xed',a:'Po tr\xe9ninku nebo v detailu tr\xe9ninku klepni na \u201eSd\xedlet\u201c. Vznikne obr\xe1zek ve form\xe1tu Instagram story \u2013 souhrn tr\xe9ninku, nebo karta nov\xe9ho osobn\xedho rekordu.'},{q:'Rychl\xfd z\xe1pis (i zp\u011btn\u011b)',a:'Den\xedk \u2192 Rychle zapsat tr\xe9nink: jeden \u0159\xe1dek = jeden cvik. P\u0159\xedklady: \u201eTrh 70x2x3, 75x2\u201c (3\xd7 2 opak. 70 kg a 1\xd7 2 opak. 75 kg), \u201eD\u0159ep 5x5 100\u201c, \u201eNadhoz 3x1@85%\u201c (z maxima), \u201eShyby 3x10\u201c. Funguje i diktov\xe1n\xed z kl\xe1vesnice. Datum m\u016f\u017ee\u0161 zm\u011bnit na d\u0159\xedv\u011bj\u0161\xed den.'}]},{id:'log',icon:'book',title:'Den\xedk a pokrok',items:[{q:'Den\xedk',a:'Tr\xe9ninky \u2192 Den\xedk: tr\xe9ninky po t\xfddnech, naho\u0159e p\xe1s dn\u016f s odtr\xe9novan\xfdmi dny. Karta ukazuje v\u0161echny cviky, celkov\xfd po\u010det n\xe1stup\u016f a ton\xe1\u017e. Klepnut\xedm otev\u0159e\u0161 detail, kde jde tr\xe9nink upravit, sd\xedlet, zopakovat nebo smazat.'},{q:'M\u016fj pokrok',a:'Den\xedk \u2192 M\u016fj pokrok: graf v\xfdvoje maxim (zapsan\xe1 maxima i nejt\u011b\u017e\u0161\xed v\xe1hy z tr\xe9nink\u016f), ton\xe1\u017e po t\xfddnech a m\u011bs\xedc\xedch a p\u0159ipravenost z den\xedku regenerace.'},{q:'Den\xedk regenerace',a:'Na kart\u011b \u201eDen\xedk regenerace\u201c zap\xed\u0161e\u0161 sp\xe1nek, energii, bolest sval\u016f, n\xe1ladu a p\u0159\xedpadnou bolest nebo zran\u011bn\xed. Aplikace z toho spo\u010d\xedt\xe1 p\u0159ipravenost 0\u2013100. \xdadaje o zdrav\xed ukl\xe1d\xe1me jen s tv\xfdm souhlasem; s tren\xe9rem je sd\xedl\xed\u0161 jen kdy\u017e to s\xe1m zapne\u0161.'}]},{id:'tools',icon:'construct',title:'N\xe1stroje',items:[{q:'Moje maxima',a:'Tr\xe9ninky \u2192 N\xe1stroje \u2192 Moje maxima. Z maxim se po\u010d\xedtaj\xed v\xe1hy v procentech. Dal\u0161\xed cviky p\u0159id\xe1\u0161 tla\u010d\xedtkem \u201eP\u0159idat cvik\u201c, v\xfdvoj uvid\xed\u0161 v \u201eGraf v\xfdvoje maxim\u201c.'},{q:'Kalkula\u010dka kotou\u010d\u016f',a:'Zadej c\xedlovou v\xe1hu a osu \u2013 aplikace uk\xe1\u017ee, jak\xe9 kotou\u010de d\xe1t na ka\u017edou stranu, i s barvami podle IWF.'},{q:'Sinclair a p\u0159evod jednotek',a:'Sinclairovy body podle aktu\xe1ln\xedch koeficient\u016f (2025\u20132028) pro mu\u017ee i \u017eeny a p\u0159evod kg \u2194 lb.'},{q:'Export tr\xe9nink\u016f',a:'Nastaven\xed \u2192 Data \u2192 Exportovat tr\xe9ninky (PDF) \u2013 p\u0159ehled tr\xe9nink\u016f do souboru, kter\xfd jde poslat tren\xe9rovi nebo vytisknout.'}]},{id:'coach',icon:'people',title:'Tren\xe9r a t\xfdm',items:[{q:'Zapnut\xed tren\xe9rsk\xe9ho re\u017eimu',a:'Nastaven\xed \u2192 Tren\xe9r \u2192 Jsem tren\xe9r. V Tr\xe9ninc\xedch se objev\xed tla\u010d\xedtko T\xfdm. Tren\xe9rsk\xfd re\u017eim je zdarma.'},{q:'Pozv\xe1n\xed sv\u011b\u0159enc\u016f',a:'T\xfdm \u2192 ikona p\u0159id\xe1n\xed: po\u0161li odkaz nebo uka\u017e QR k\xf3d. Sv\u011b\u0159enec pozv\xe1nku potvrd\xed a s\xe1m rozhodne, jestli tren\xe9r uvid\xed i jeho t\u011blesnou hmotnost a den\xedk regenerace. Nezletil\xfd sv\u011b\u0159enec se m\u016f\u017ee p\u0159ipojit jen k tren\xe9rovi ze stejn\xe9ho klubu.'},{q:'P\u0159ehled t\xfdmu \u2013 z\xe1lo\u017eka Dnes',a:'Kdo dnes tr\xe9noval, kdo je\u0161t\u011b tr\xe9nink m\xe1, kdo vynechal pl\xe1novan\xfd tr\xe9nink, kdo hl\xe1s\xed bolest nebo m\xe1 n\xedzkou p\u0159ipravenost a kdo dlouho netr\xe9noval. Klepnut\xedm otev\u0159e\u0161 den\xedk sv\u011b\u0159ence.'},{q:'Pl\xe1ny pro sv\u011b\u0159ence',a:'Vytvo\u0159 pl\xe1n (v procentech, kilech, RPE nebo bez z\xe1t\u011b\u017ee) a klepni na \u201ePoslat sv\u011b\u0159enc\u016fm\u201c \u2013 vyber jednotlivce nebo skupinu. Pl\xe1n v kilech je dobr\xe9 poslat ka\u017ed\xe9mu zvl\xe1\u0161\u0165. \xdapravy pl\xe1nu se sv\u011b\u0159enc\u016fm prom\xedtnou.'},{q:'Skupiny, \u017eeb\u0159\xed\u010dek, koment\xe1\u0159e',a:'Skupiny (nap\u0159. Junio\u0159i) usnadn\xed pos\xedl\xe1n\xed pl\xe1n\u016f. \u017deb\u0159\xed\u010dek \u0159ad\xed t\xfdm podle Sinclairu a maxim. K tr\xe9nink\u016fm sv\u011b\u0159enc\u016f m\u016f\u017ee\u0161 ps\xe1t koment\xe1\u0159e a prohl\xed\u017eet videa, kter\xe1 ti po\u0161lou.'}]},{id:'social',icon:'chatbubbles',title:'V\xfdzva, p\u0159\xe1tel\xe9 a zpr\xe1vy',items:[{q:'V\xfdzva m\u011bs\xedce',a:'Ka\u017ed\xfd m\u011bs\xedc nov\xe9 t\xe9ma. Nahraj video (tla\u010d\xedtko nahr\xe1n\xed), prohl\xed\u017eej videa ostatn\xedch a lajkuj. Video s nejv\xedc lajky na konci m\u011bs\xedce vyhr\xe1v\xe1 titul Vzp\u011bra\u010d m\u011bs\xedce. Nahr\xe1vej jen videa, ke kter\xfdm m\xe1\u0161 pr\xe1va (i hudba).'},{q:'P\u0159\xe1tel\xe9 a zpr\xe1vy',a:'Profil \u2192 ikony vlevo naho\u0159e. P\u0159\xe1tele p\u0159id\xe1\u0161 z jejich profilu. Zpr\xe1vy od lid\xed, kte\u0159\xed nejsou tvoji p\u0159\xe1tel\xe9, p\u0159ijdou jako \u017e\xe1dost.'},{q:'Nahl\xe1\u0161en\xed a blokov\xe1n\xed',a:'U profilu, zpr\xe1vy nebo videa p\u0159es \u22ef \u2192 Nahl\xe1sit. U\u017eivatele m\u016f\u017ee\u0161 zablokovat; seznam blokovan\xfdch je v Nastaven\xed \u2192 Soukrom\xed. P\u0159i odstran\u011bn\xed obsahu dostane\u0161 ozn\xe1men\xed s d\u016fvodem a m\u016f\u017ee\u0161 do 6 m\u011bs\xedc\u016f po\u017e\xe1dat o p\u0159ezkum.'}]},{id:'notify',icon:'notifications',title:'Upozorn\u011bn\xed, widget, hodinky',items:[{q:'Upozorn\u011bn\xed',a:'Nastaven\xed \u2192 Upozorn\u011bn\xed: p\u0159ipom\xednka tr\xe9ninku v pl\xe1novan\xfd den (\u010das si zvol\xed\u0161), nov\xfd pl\xe1n a koment\xe1\u0159e od tren\xe9ra, nov\xe9 zpr\xe1vy a z\xe1vody tv\xe9ho klubu. Upozorn\u011bn\xed funguj\xed v mobiln\xed aplikaci, ne ve webov\xe9 verzi.'},{q:'Widget na plo\u0161e',a:'Podr\u017e prst na plo\u0161e telefonu \u2192 p\u0159idat widget \u2192 Zvedej. Ukazuje dne\u0161n\xed tr\xe9nink z pl\xe1nu, t\xfddny v \u0159ad\u011b a odtr\xe9novan\xe9 dny t\xfddne.'},{q:'Hodinky',a:'Ozn\xe1men\xed o konci pauzy se samo zobraz\xed na Apple Watch i Wear OS \u2013 p\u0159\xedmo z hodinek od\u0161krtne\u0161 n\xe1stup nebo p\u0159id\xe1\u0161 30 s.'},{q:'Bez sign\xe1lu',a:'Tr\xe9ninky si zapisuje\u0161 i bez internetu. Zm\u011bny \u010dekaj\xed v telefonu (uk\xe1\u017ee se \u201eBez sign\xe1lu \u2013 tr\xe9ninky se ukl\xe1daj\xed do telefonu\u201c) a ode\u0161lou se samy, jakmile se p\u0159ipoj\xed\u0161.'}]},{id:'privacy',icon:'shield-checkmark',title:'\xda\u010det a soukrom\xed',items:[{q:'Kdo vid\xed m\u016fj profil',a:'Nastaven\xed \u2192 Soukrom\xed: viditelnost profilu ve vyhled\xe1v\xe1n\xed a zobrazen\xed t\u011blesn\xe9 hmotnosti ostatn\xedm (ve v\xfdchoz\xedm stavu skryt\xe1). Profily nezletil\xfdch jsou skryt\xe9 automaticky.'},{q:'Moje data',a:'Nastaven\xed \u2192 Data \u2192 St\xe1hnout v\u0161echna moje data (JSON). \xda\u010det a v\u0161echna data sma\u017ee\u0161 v Nastaven\xed \u2192 Smazat \xfa\u010det.'},{q:'D\u011bti a souhlas rodi\u010d\u016f',a:'Aplikaci mohou pou\u017e\xedvat lid\xe9 od 13 let. Do 15 let (\u010cesko) nebo 16 let (Slovensko a jinde) je pot\u0159eba souhlas rodi\u010de \u2013 aplikace mu po\u0161le odkaz. Do t\xe9 doby funguje jen tr\xe9ninkov\xfd den\xedk.'}]},{id:'faq',icon:'help-buoy',title:'\u010cast\xe9 ot\xe1zky',items:[{q:'Pl\xe1n mi po\u010d\xedt\xe1 divn\xe9 v\xe1hy',a:'V\xe1hy v procentech se po\u010d\xedtaj\xed z maxim v N\xe1stroje \u2192 Moje maxima. Zkontroluj, \u017ee m\xe1\u0161 maximum zadan\xe9 u spr\xe1vn\xe9ho cviku (nap\u0159. p\u0159em\xedst\u011bn\xed se po\u010d\xedt\xe1 z nadhozu). Bez maxim zvol pl\xe1n podle RPE.'},{q:'Neukl\xe1d\xe1 se mi tr\xe9nink',a:'Ulo\u017e\xed se jen od\u0161krtnut\xe9 n\xe1stupy. Bez sign\xe1lu se tr\xe9nink ulo\u017e\xed v telefonu a ode\u0161le se pozd\u011bji \u2013 neodinstalov\xe1vej aplikaci, dokud se neode\u0161le.'},{q:'Nechod\xed mi upozorn\u011bn\xed',a:'Zkontroluj Nastaven\xed \u2192 Upozorn\u011bn\xed a povolen\xed upozorn\u011bn\xed v nastaven\xed telefonu. Ve webov\xe9 verzi upozorn\u011bn\xed nefunguj\xed.'},{q:'Na\u0161el jsem chybu / m\xe1m n\xe1pad',a:'Napi\u0161 n\xe1m p\u0159es Nastaven\xed \u2192 Provozovatel a kontakt. Kdy\u017e se aplikace pokaz\xed, na chybov\xe9 obrazovce je tla\u010d\xedtko pro odesl\xe1n\xed hl\xe1\u0161en\xed.'}]}]},1094,[]);